# frozen_string_literal: true

# Who can join one organization, and how: email domains (with domain
# verification and the sign-up policy), join codes, the allowlist, and the
# queue of pending join requests. Every change goes through the gem's
# models, never raw row writes.
#
# Generated by `rails g organizations:join`. It is yours now: change the
# copy, the layout and the URL. Keep the safety rules below.
#
# Safety rules:
#   - Organizations::OrganizationScoped takes the organization from the URL,
#     and every lookup below is scoped to it, so an id from another
#     organization is a 404.
#   - The page needs the invite_members permission; domain changes also need
#     manage_settings. Unknown organizations, strangers and members without
#     the permission all get the same 404, so the page reveals nothing.
#   - Only the domain name and the join policy come from params. The
#     verification columns are written by the gem's methods only.
#   - Lists from params are cut to a fixed size.
#   - DNS checks are rate limited (Rails 7.2+).
class OrganizationAccessController < ApplicationController
  include Organizations::OrganizationScoped

  MAX_ALLOWLIST_IMPORT = 1_000
  MAX_ALLOWLIST_INPUT = 300_000 # characters, about 1,000 long addresses
  MAX_LABEL_LENGTH = 100

  before_action -> { send(Organizations.configuration.authenticate_user_method) }
  self.organization_param = :organization_id
  require_organization_permission :invite_members
  require_organization_permission :manage_settings, only: %i[add_domain update_domain remove_domain
                                                             start_domain_verification verify_domain]

  # Rails 7.2+, with a shared cache store (see OrganizationJoinsController).
  rate_limit to: 10, within: 10.minutes, by: -> { viewer.id }, only: :verify_domain if respond_to?(:rate_limit)

  helper_method :organization

  def show
    @domains = organization.domains.order(:domain)
    @join_codes = organization.join_codes.order(created_at: :desc)
    @allowlist_entries = organization.allowlist_entries.unclaimed.order(:email)
    @pending_requests = organization.join_requests.pending.includes(:user).order(created_at: :asc)
  end

  def add_domain
    organization.add_domain!(params[:domain].to_s.first(253))
    back notice: "Domain added. Verify it before it can admit anyone when verification is required."
  rescue ActiveRecord::RecordInvalid => e
    back alert: e.message
  end

  def update_domain
    domain.update!(join_policy: params[:join_policy].to_s)
    back notice: "Join policy saved. It acts once the domain is verified."
  rescue ActiveRecord::RecordInvalid => e
    back alert: e.message
  end

  def remove_domain
    domain.destroy!
    back notice: "Domain removed. Existing members keep their membership."
  end

  def start_domain_verification
    domain.start_verification!
    back notice: "Add the TXT record below to your DNS, then press Verify."
  end

  def verify_domain
    domain.verify!
    back notice: "#{domain.domain} is verified."
  rescue Organizations::DomainVerificationFailed => e
    back alert: e.message
  end

  def generate_code
    code = organization.generate_join_code!(
      label: params[:label].to_s.first(MAX_LABEL_LENGTH).presence,
      auto_approve: params[:auto_approve] == "1",
      created_by: viewer
    )
    back notice: "Code #{code.display_code} created."
  end

  def revoke_code
    organization.join_codes.find(params[:code_id]).revoke!
    back notice: "Code revoked. To rotate a code, revoke it and create a new one."
  end

  # Valid addresses are imported; the rest are counted and skipped.
  def import_allowlist
    tokens = params[:emails].to_s.first(MAX_ALLOWLIST_INPUT).split(/[\s,;]+/, MAX_ALLOWLIST_IMPORT + 1)
    tokens = tokens.compact_blank.first(MAX_ALLOWLIST_IMPORT)
    valid, invalid = tokens.partition { |email| email.length <= 254 && email.match?(URI::MailTo::EMAIL_REGEXP) }
    imported = organization.import_allowlist!(valid, source: "manual")
    message = "#{imported.size} address(es) added to the allowlist."
    message += " #{invalid.size} skipped: not an email address." if invalid.any?
    back notice: message
  end

  def remove_allowlist_entry
    organization.allowlist_entries.unclaimed.find(params[:entry_id]).destroy!
    back notice: "Address removed from the allowlist."
  end

  # Hard limits (seats) belong in config.on_member_joining: the gate also
  # covers this path, so there is no check to repeat here.
  def approve_request
    request = organization.join_requests.find(params[:request_id])
    organization.approve_join_request!(request, approved_by: viewer)
    back notice: "#{request.user.email} is now a member."
  rescue Organizations::MembershipVetoed, Organizations::JoinRequestError => e
    back alert: e.message
  end

  def reject_request
    request = organization.join_requests.find(params[:request_id])
    reason = params[:reason].to_s.first(500).presence
    organization.reject_join_request!(request, rejected_by: viewer, reason: reason)
    back notice: "Request rejected."
  rescue Organizations::JoinRequestError => e
    back alert: e.message
  end

  private

  def organization
    current_scoped_organization
  end

  # The signed-in user, through config.current_user_method.
  def viewer
    send(Organizations.configuration.current_user_method)
  end

  def domain
    @domain ||= organization.domains.find(params[:domain_id])
  end

  # 303, so a browser follows a POST or DELETE with a GET.
  def back(**messages)
    redirect_to organization_access_path(organization), status: :see_other, **messages
  end
end
